// Package postgres is the datastore: tenants, users, functions, versions and
// invocations. Queries are generated by sqlc from queries/ against
// migrations/.
package postgres

import (
	"context"
	"embed"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"

	"github.com/galaxy-io/alchemy/datastore/postgres/sqlcgen"
)

// DefaultTenantID is the built-in tenant seeded by the first migration and
// used while callers carry no identity.
const DefaultTenantID = "00000000-0000-0000-0000-000000000000"

//go:embed migrations/*.sql
var migrations embed.FS

// Store is a connection pool plus the generated queries.
type Store struct {
	*sqlcgen.Queries
	pool *pgxpool.Pool
}

// Open connects to dsn and pings it.
func Open(ctx context.Context, dsn string) (*Store, error) {
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return nil, fmt.Errorf("datastore/postgres: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("datastore/postgres: ping: %w", err)
	}
	return &Store{Queries: sqlcgen.New(pool), pool: pool}, nil
}

// Close releases the pool.
func (s *Store) Close() { s.pool.Close() }

// Migrate applies pending migrations. server runs it on every start;
// goose keeps its own version table.
func (s *Store) Migrate(ctx context.Context) error {
	db := stdlib.OpenDBFromPool(s.pool)
	defer func() { _ = db.Close() }()
	goose.SetBaseFS(migrations)
	if err := goose.SetDialect("postgres"); err != nil {
		return fmt.Errorf("datastore/postgres: set dialect: %w", err)
	}
	if err := goose.UpContext(ctx, db, "migrations"); err != nil {
		return fmt.Errorf("datastore/postgres: migrate: %w", err)
	}
	return nil
}
